DECLARE @G07Actual_foreignKeys NVARCHAR(MAX)=(SELECT fk.name,ps.name fromSchema,pt.name fromTable,rs.name toSchema,rt.name toTable,fk.is_disabled isDisabled,fk.is_not_trusted isNotTrusted,fk.delete_referential_action_desc onDelete,fk.update_referential_action_desc onUpdate,JSON_QUERY((SELECT pc.name fromColumn,rc.name toColumn,fc.constraint_column_id ordinal FROM sys.foreign_key_columns fc JOIN sys.columns pc ON pc.object_id=fc.parent_object_id AND pc.column_id=fc.parent_column_id JOIN sys.columns rc ON rc.object_id=fc.referenced_object_id AND rc.column_id=fc.referenced_column_id WHERE fc.constraint_object_id=fk.object_id ORDER BY fc.constraint_column_id FOR JSON PATH)) columns FROM sys.foreign_keys fk JOIN sys.tables pt ON pt.object_id=fk.parent_object_id JOIN sys.schemas ps ON ps.schema_id=pt.schema_id JOIN sys.tables rt ON rt.object_id=fk.referenced_object_id JOIN sys.schemas rs ON rs.schema_id=rt.schema_id WHERE pt.is_ms_shipped=0 AND pt.name NOT IN (N'sysdiagrams',N'sysdiagram_properties',N'dtproperties') ORDER BY ps.name,pt.name,fk.name FOR JSON PATH);
IF HASHBYTES('SHA2_256',COALESCE(@G07Actual_foreignKeys,N''))<>HASHBYTES('SHA2_256',@G07Expected_foreignKeys)
 THROW 51016,'G07_SCHEMA_MISMATCH_foreignKeys',1;
GO
DECLARE @G07Owner INT=DATABASE_PRINCIPAL_ID(N'dbo'),@G07Result INT;
DECLARE @G07Definition VARBINARY(MAX);
IF NOT EXISTS(SELECT 1 FROM dbo.sysdiagrams WHERE name=N'G07 - Modelo de datos completo' AND principal_id=@G07Owner)
 EXEC @G07Result=dbo.sp_creatediagram @diagramname=N'G07 - Modelo de datos completo',@owner_id=@G07Owner,@version=1,@definition=@G07Definition;
ELSE IF EXISTS(SELECT 1 FROM dbo.sysdiagrams WHERE name=N'G07 - Modelo de datos completo' AND principal_id=@G07Owner AND (version IS NULL OR version<>1 OR definition IS NULL OR HASHBYTES('SHA2_256',definition)<>HASHBYTES('SHA2_256',@G07Definition)))
 EXEC @G07Result=dbo.sp_alterdiagram @diagramname=N'G07 - Modelo de datos completo',@owner_id=@G07Owner,@version=1,@definition=@G07Definition;
IF @G07Result<0 THROW 51016,'G07_NATIVE_DIAGRAM_WRITE_FAILED',1;
IF NOT EXISTS(SELECT 1 FROM dbo.sysdiagrams WHERE name=N'G07 - Modelo de datos completo' AND principal_id=@G07Owner AND version=1 AND HASHBYTES('SHA2_256',definition)=HASHBYTES('SHA2_256',@G07Definition)) THROW 51016,'G07_NATIVE_DIAGRAM_READBACK_FAILED',1;
GO
